import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/codex/commands.md","filePath":"en/modules/codex/commands.md","lastUpdated":0}`),a={name:`en/modules/codex/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to “Commands”">​</a></h1><p>EmakiCodex uses <code>/codex</code> as its main command and <code>/ecodex</code> as an alias. Both <code>codex</code> and <code>open</code> open the category-entry codex GUI; documentation examples use <code>/codex</code>.</p><p>The normal entry checks <code>emakicodex.use</code>; <code>emakicodex.admin</code> bypasses the use, reload, and debug checks. All administrative targets currently have to be online players.</p><h2 id="command-list" tabindex="-1">Command list <a class="header-anchor" href="#command-list" aria-label="Permalink to “Command list”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/codex</code> / <code>/codex help</code></td><td><code>emakicodex.use</code></td><td>Shows help.</td></tr><tr><td><code>/codex codex</code> / <code>/codex open</code></td><td><code>emakicodex.use</code> or <code>emakicodex.admin</code></td><td>Opens the category-entry codex GUI.</td></tr><tr><td><code>/codex reload</code></td><td><code>emakicodex.reload</code> or <code>emakicodex.admin</code></td><td>Reloads config, language files, vanilla advancement pages, category entries, and GUI templates; rebuilds registrations and tries to resync online players.</td></tr><tr><td><code>/codex grant &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>Grants one vanilla Codex advancement to an online player.</td></tr><tr><td><code>/codex revoke &lt;player&gt; &lt;advId&gt;</code></td><td><code>emakicodex.admin</code></td><td>Revokes one vanilla Codex advancement from an online player.</td></tr><tr><td><code>/codex admin unlock &lt;player&gt; &lt;category/entry&gt;</code></td><td><code>emakicodex.admin</code></td><td>Directly unlocks one category entry without activating or claiming it.</td></tr><tr><td><code>/codex admin reset &lt;player&gt; [category/entry]</code></td><td><code>emakicodex.admin</code></td><td>Resets one category entry, or all category-entry state when the composite id is omitted.</td></tr><tr><td><code>/codex debug ...</code></td><td><code>emakicodex.debug</code> or <code>emakicodex.admin</code></td><td>Manages the <code>advancement</code> debug module. Detailed subcommands are provided by CoreLib DebugCommand.</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/codex</span></span>
<span class="line"><span>/codex codex</span></span>
<span class="line"><span>/codex open</span></span>
<span class="line"><span>/codex reload</span></span>
<span class="line"><span>/codex grant Steve example/first_step</span></span>
<span class="line"><span>/codex grant Steve emakicodex:example/challenge</span></span>
<span class="line"><span>/codex revoke Steve example/first_step</span></span>
<span class="line"><span>/codex admin unlock Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve example/first_blood</span></span>
<span class="line"><span>/codex admin reset Steve</span></span>
<span class="line"><span>/codex debug advancement on</span></span>
<span class="line"><span>/codex debug advancement off</span></span></code></pre></div><p><code>grant</code> and <code>revoke</code> require the target player to be online because the current implementation matches online player names exactly. <code>admin unlock/reset</code> also require an online target. Vanilla <code>advId</code> supports two forms:</p><table tabindex="0"><thead><tr><th>Form</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><code>page/node</code></td><td><code>example/first_step</code></td><td>Recommended short form for server administrators.</td></tr><tr><td>Full NamespacedKey</td><td><code>emakicodex:example/first_step</code></td><td>Matches the underlying vanilla advancement key.</td></tr></tbody></table><p>Category-entry commands use the composite id from <code>codex/*.yml</code>, not a vanilla NamespacedKey:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;category_id&gt;/&lt;entry_id&gt;</span></span></code></pre></div><p>For example, <code>example/first_blood</code>. <code>admin unlock</code> changes only the unlocked state; a left click in the GUI activates attribute rewards, while a right click performs the one-time <code>rewards.actions</code> claim.</p><h2 id="reload-behavior" tabindex="-1">Reload behavior <a class="header-anchor" href="#reload-behavior" aria-label="Permalink to “Reload behavior”">​</a></h2><p><code>/codex reload</code> performs these operations:</p><ol><li>Releases missing default resources, controlled by <code>config.yml &gt; release_default_data</code>.</li><li>Reloads <code>config.yml</code>, <code>lang/*.yml</code>, <code>advancements/*.yml</code>, <code>codex/*.yml</code>, and GUI templates.</li><li>Removes and re-registers dynamic advancements under the EmakiCodex namespace, then rebuilds category entries and reward providers.</li><li>If PacketEvents is available, re-pushes the vanilla advancement tree to online players; otherwise online players may need to reconnect to see advancement UI changes.</li><li>Keeps player category-entry data in <code>data/&lt;uuid&gt;.yml</code> and derives attribute rewards again from the new configuration.</li></ol><h2 id="permission-nodes" tabindex="-1">Permission nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission nodes”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Covers</th></tr></thead><tbody><tr><td><code>emakicodex.use</code></td><td><code>true</code></td><td>Use help, the category-entry GUI (<code>codex/open</code>), and the normal command entry.</td></tr><tr><td><code>emakicodex.reload</code></td><td><code>op</code></td><td>Use <code>/codex reload</code>. Can be replaced by <code>emakicodex.admin</code>.</td></tr><tr><td><code>emakicodex.debug</code></td><td><code>op</code></td><td>Use <code>/codex debug ...</code>. Can be replaced by <code>emakicodex.admin</code>.</td></tr><tr><td><code>emakicodex.admin</code></td><td><code>op</code></td><td>Use <code>grant</code>, <code>revoke</code>, and <code>admin unlock/reset</code>, and override use/reload/debug checks.</td></tr></tbody></table><p>Common LuckPerms examples:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/lp group default permission set emakicodex.use true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.admin true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.reload true</span></span>
<span class="line"><span>/lp group admin permission set emakicodex.debug true</span></span></code></pre></div><h2 id="common-failure-cases" tabindex="-1">Common failure cases <a class="header-anchor" href="#common-failure-cases" aria-label="Permalink to “Common failure cases”">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>Explanation</th></tr></thead><tbody><tr><td><code>Player not found</code></td><td>The <code>grant</code> / <code>revoke</code> target is offline, or the name is not an exact match.</td></tr><tr><td><code>Advancement ... is not registered or unchanged</code></td><td>The advancement ID is wrong, the page failed to load, or the player&#39;s progress did not change.</td></tr><tr><td><code>category/entry</code> is not found</td><td>The category file did not load, the composite id is misspelled, or the entry has not been unlocked.</td></tr><tr><td><code>admin unlock</code> succeeds but no attributes appear</td><td><code>unlock</code> changes only the unlocked state; activate the entry in the GUI, and ensure it declares <code>rewards.attributes</code>.</td></tr><tr><td>A right-click claim fails</td><td>The entry is locked, has no <code>rewards.actions</code>, or has already been claimed; claims are one-time.</td></tr><tr><td>Online players cannot see new nodes after reload</td><td>PacketEvents is missing or resync failed; players should reconnect.</td></tr><tr><td>Node coordinates do not apply</td><td>PacketEvents must be installed and <code>advancement.packet_coordinates: true</code> must be enabled.</td></tr></tbody></table>`,21)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};